import Foundation
import XCTest
@testable import ColorComposerCore

/// Replays the versioned golden vectors generated by
/// `viamin/color_matching`'s `mix parity.generate` task. Keep this test and
/// its fixture together: the fixture is the cross-repository contract, not a
/// hand-maintained collection of examples.
final class WeightedSquaredErrorParityTests: XCTestCase {
    func testVersionOneCorpusMatchesScorerAndSolverSelectionsExactly() throws {
        let corpus = try loadCorpus()

        XCTAssertEqual(corpus.algorithmVersion, 1)
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.lightSources, ["white", "red", "green", "blue", "lps"])

        for scenario in corpus.scenarios {
            try assertParity(for: scenario)
        }
    }

    private func assertParity(for scenario: ParityScenario) throws {
        let scorer = WeightedSquaredErrorScorer()
        let weights = makeWeights(from: scenario.weights)
        let target = TargetResponseVector(makeResponses(from: scenario.target.channels))
        let palette = try scenario.palette.map(makePaletteColor)
        let expectedScores = Dictionary(uniqueKeysWithValues: scenario.expected.scores.map { ($0.index, $0.score) })

        XCTAssertEqual(expectedScores.count, palette.count, scenario.id)

        var selected: (index: Int, score: Double)?
        var actualScores: [Int: ParityScore] = [:]
        for (index, candidate) in palette.enumerated() {
            let actual: ParityScore
            switch scorer.score(candidate: candidate, target: target, weights: weights) {
            case .excluded:
                actual = .excluded
            case .score(let score):
                actual = .score(score)
                if selected == nil || score < selected!.score {
                    selected = (index, score)
                }
            }
            actualScores[index] = actual
            XCTAssertEqual(actual, expectedScores[index], "\(scenario.id), candidate \(index)")
        }

        XCTAssertEqual(selected?.index, scenario.expected.selectedIndex, scenario.id)
        XCTAssertEqual(selected?.score, scenario.expected.error, scenario.id)
        XCTAssertEqual(selected.map { palette[$0.index].hex }, scenario.expected.selectedHexColor, scenario.id)

        let tiedIndices = actualScores.compactMap { index, score in
            score == selected.map(ParityScore.score) ? index : nil
        }.sorted()
        XCTAssertEqual(tiedIndices, scenario.expected.tiedIndices, scenario.id)
        XCTAssertEqual(tiedIndices.count > 1, scenario.expected.tieBroke ?? false, scenario.id)

        try assertFastPathSelection(
            scenario: scenario,
            palette: palette,
            weights: weights,
            selected: selected
        )
    }

    private func assertFastPathSelection(
        scenario: ParityScenario,
        palette: [PaletteColor],
        weights: ChannelWeights,
        selected: (index: Int, score: Double)?
    ) throws {
        let active = weights.activeConditions
        guard active.allSatisfy({ scenario.target.channels[$0.rawValue] != nil }) else {
            // CompositionSolver correctly rejects an absent source grid; the
            // scorer replay above remains the parity assertion for this
            // intentionally incomplete target vector.
            return
        }

        let grids = Dictionary(uniqueKeysWithValues: active.map { condition in
            (condition, BrightnessGrid(width: 1, height: 1, fill: scenario.target.channels[condition.rawValue]!))
        })
        let result = try CompositionSolver().solve(palette: palette, sourceGrids: grids, weights: weights)

        XCTAssertEqual(result.colorIndices[0], selected?.index, scenario.id)
        if let selected {
            XCTAssertEqual(result.errors[0], selected.score, scenario.id)
        } else {
            XCTAssertEqual(result.errors[0], .infinity, scenario.id)
        }
    }

    private func loadCorpus() throws -> ParityCorpus {
        let fixture = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/weighted_squared_error_v1.json")
        return try JSONDecoder().decode(ParityCorpus.self, from: Data(contentsOf: fixture))
    }

    private func makeWeights(from values: [String: Double]) -> ChannelWeights {
        ChannelWeights(
            white: values["white"] ?? 0,
            red: values["red"] ?? 0,
            green: values["green"] ?? 0,
            blue: values["blue"] ?? 0,
            lps: values["lps"] ?? 0
        )
    }

    private func makeResponses(from values: [String: Double]) -> [LightingCondition: Double] {
        Dictionary(uniqueKeysWithValues: values.compactMap { key, value in
            LightingCondition(rawValue: key).map { ($0, value) }
        })
    }

    private func makePaletteColor(_ entry: ParityVector) throws -> PaletteColor {
        PaletteColor(
            id: try XCTUnwrap(entry.index),
            hex: entry.hexColor,
            rgb: try XCTUnwrap(RGBColor(hex: entry.hexColor)),
            responses: makeResponses(from: entry.channels).mapValues(IlluminationResponse.init(brightness:))
        )
    }
}

private struct ParityCorpus: Decodable {
    let algorithmVersion: Int
    let lightSources: [String]
    let missingPolicy: String
    let scenarios: [ParityScenario]
    let scorer: String
    let selection: String
}

private struct ParityScenario: Decodable {
    let expected: ParityExpected
    let id: String
    let palette: [ParityVector]
    let target: ParityVector
    let weights: [String: Double]
}

private struct ParityVector: Decodable {
    let channels: [String: Double]
    let hexColor: String
    let index: Int?
}

private struct ParityExpected: Decodable {
    let error: Double?
    let scores: [ParityExpectedScore]
    let selectedHexColor: String?
    let selectedIndex: Int?
    let tieBroke: Bool?
    let tiedIndices: [Int]
}

private struct ParityExpectedScore: Decodable {
    let index: Int
    let score: ParityScore
}

private enum ParityScore: Decodable, Equatable {
    case excluded
    case score(Double)

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Double.self) {
            self = .score(value)
        } else if try container.decode(String.self) == "excluded" {
            self = .excluded
        } else {
            throw DecodingError.dataCorruptedError(in: container, debugDescription: "Expected a score or excluded")
        }
    }
}
